import chisel3._

class Add extends Module {
  val io = IO(new Bundle {
    val a = Input(UInt(8.W))
    val b = Input(UInt(8.W))
    val y = Output(UInt(8.W))
  })
  io.y := io.a + io.b
}

switch (io.sel) {
  is (0.U) { io.y := io.a }
  is (1.U) { io.y := io.b }
  is (2.U) { io.y := io.c }
}

val mem = Mem(32, UInt(8.W))
when (io.wen) {
  mem.write(io.waddr, io.wdata)
}
io.rdata := mem.read(io.raddr)

val ram = SyncReadMem(32, UInt(8.W))
when (io.wen) {
  ram.write(io.waddr, io.wdata)
}
io.rdata := ram.read(io.raddr, io.ren)

class Host extends Module {
  val io = IO(new Bundle {
    val out = Decoupled(UInt(8.W))
  })
  io.out.valid := true.B
  io.out.bits  := 7.U
}

val idle :: load :: done :: Nil = Enum(3)
val state = RegInit(idle)

switch (state) {
  is (idle) {
    when (io.start) { state := load }
  }
  is (load) {
    state := done
  }
  is (done) {
    io.finished := true.B
    state := idle
  }
}

import chisel3._
import chisel3.util._

class NutSorter extends Module {
  val io = IO(new Bundle {
    val start  = Input(Bool())
    val in     = Flipped(Decoupled(UInt(2.W)))
    val acorns = Output(UInt(8.W))
    val walnuts = Output(UInt(8.W))
    val done   = Output(Bool())
  })

  val idle :: run :: report :: Nil = Enum(3)
  val state = RegInit(idle)
  val acorns  = RegInit(0.U(8.W))
  val walnuts = RegInit(0.U(8.W))

  io.in.ready := false.B
  io.done     := false.B
  io.acorns   := acorns
  io.walnuts  := walnuts

  switch (state) {
    is (idle) {
      when (io.start) {
        acorns  := 0.U
        walnuts := 0.U
        state   := run
      }
    }
    is (run) {
      io.in.ready := true.B
      when (io.in.fire) {
        when (io.in.bits === 0.U) { acorns  := acorns + 1.U }
        .elsewhen (io.in.bits === 1.U) { walnuts := walnuts + 1.U }
      }
      when (!io.start) { state := report }
    }
    is (report) {
      io.done := true.B
      when (!io.start) { state := idle }
    }
  }
}
